    items = sorted(vertices)
    for r in range(len(items) + 1):
        for s in combinations(items, r):
            yield frozenset(s)

def stable(vertices: set[int], attacks: set[Edge], s: frozenset[int]) -> bool:
    return (all(not (u in s and v in s) for u, v in attacks) and
            all(x in s or any(u in s and v == x for u, v in attacks) for x in vertices))

def kernel(vertices: set[int], edges: set[Edge], k: frozenset[int]) -> bool:
    return (all(not (u in k and v in k) for u, v in edges) and
            all(x in k or any(u == x and v in k for u, v in edges) for x in vertices))

vertices = {0, 1, 2, 3}
attacks = {(0, 1), (1, 2), (2, 3), (3, 0)}
reverse = {(v, u) for u, v in attacks}
for s in subsets(vertices):
    assert stable(vertices, attacks, s) == kernel(vertices, reverse, s)
print("Stable sets equal kernels after reversal for every subset.")

